code.perFrame:
time=gettime(0); dt=time-last; last=time;
optimizer=pow(.9,30*dt);

spec=getspec(sound*(sound*.1375+sound*
          .1175)+spec,.1875,0);
input=sound*bnot(input*pow(input,input))+
          (sound*.1375+sound*.1175); 
sound=vinput*.0875+getspec(.1875*((sound*.1375+
            sound*.1175)*spec)+.25*(sound*spec),.1875,0);
music=sound+(spec*(sound*.1375+sound*.1175))*
           .1675+(input*.1125);
engine=music*.01;

asp=h/w; aspr=1/asp;

reg00=dt; reg01=optimizer;
reg02=music; reg03=engine;
reg04=dt*engine;
reg05=asp; reg06=aspr;

rote=rote+reg04*reg01;
rotb=reg01*rotb+(1-reg01)*rotb*
        (reg01+(rote*reg00)-rote*reg01);
rot=rotb*.325+rot*.99+rote;

switche=switche+reg04*reg01;
switchb=reg01*switchb+(1-reg01)*switchb*
              (reg01+(switche*reg00)-switche*reg01); 
switch=switchb*.325+switch*.9125;

movxe=movxe+reg04*reg01;
movxb=reg01*movxb+(1-reg01)*movxe*
             (reg01+(movxe*reg00)-movxb*reg01);
movx=movxb*.325+movx*.99+movxe; cmov=cos(movx);

movye=movye+reg04*reg01;
movyb=reg01*movyb+(1-reg01)*movye*
             (reg01+(movye*reg00)-movyb*reg01);
movy=movyb*.325+movy*.99+movye; smov=sin(movy);

motx=motx*.95;
moty=moty*.95;
xmog=xmog+motx;
smog=sin(xmog)*.8;
ymog=ymog+moty;
cmog=cos(ymog)*.8

code.onBeat:
rotb=rand(10)/20-.25; rote=-rote;
switchb=rand(100)/200-.25;
movxb=rand(400)/200-2;
movyb=rand(400)/200-2;

motx=rand(200)/1000-.1;
moty=rand(200)/1000-.1;

code.perPoint:
x=x+smog; y=(y+cmog)*reg05;
r1=atan2(y,x); r2=atan2(x,y);
r=(r1-r2)+rot;
d=.75*invsqrt(sqr(x)+sqr(y))*.8+.5;
r=r+switch*sqr(d)+rot;
x=cos(r)*d-cmov; y=(sin(r)*d-smov)*reg06;

alpha=(.4/sqr(d))/(reg02/.375);
